"""Exercise scientific acceptance boundaries without launching a JVM or fabricating benchmark evidence."""
import copy
import importlib.util
import json
from pathlib import Path
import tempfile
import unittest


HERE = Path(__file__).resolve().parent


def load(name, filename):
    spec = importlib.util.spec_from_file_location(name, HERE / filename)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


DRIVER = load('qualified_driver', 'run-comparison.py')
ANALYZER = load('qualified_analyzer', 'analyze-timing-independent.py')


class QualificationTest(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.folder = Path(self.temp.name)
        self.samples = []
        self.records = [{
            'format': 1, 'type': 'accountingMetadata', 'scope': DRIVER.ACCOUNTING_SCOPE,
            'fixture': 'shared-tail', 'delegateLauncher': DRIVER.FIXTURES['shared-tail']['launcher'],
            'harnessReturned': True, 'harnessFailureClass': None, 'capacity': 13,
            'opened': 13, 'closed': 13, 'size': 13, 'overflowCount': 0}]
        for index in range(13):
            self.samples.append({'iteration': index - 8, 'stage': 'warmup' if index < 8 else 'measurement',
                'counters': {'lazyValueCalls': 100, 'semanticNativeCompiles': 1,
                    'compiledBinds': 1, 'interpretedBinds': 0, 'aggregateCompiledBinds': 0,
                    'aggregateInterpretedBinds': 0}, 'successfulSelections': [{'mode': 'AUTO'}],
                'adjacency': {'lookupHits': 1}})
            record = {key: 0 for key in DRIVER.ACCOUNTING_FIELDS}
            record.update({'type': 'owner', 'recordIndex': index, 'ownerOrdinal': index + 1,
                'compileOrdinalAtOpen': index + 1, 'compileOrdinalAtClose': index + 1,
                'lazyValueCallsAtOpen': 100 * index, 'lazyValueCallsAtClose': 100 * (index + 1)})
            self.records.append(record)

    def tearDown(self):
        self.temp.cleanup()

    def write(self):
        (self.folder / 'miss-accounting.jsonl').write_text(
            '\n'.join(json.dumps(record) for record in self.records) + '\n')

    def validate_both(self):
        self.write()
        return (DRIVER.validate_accounting(self.folder, 'shared-tail', self.samples),
                ANALYZER.read_accounting(self.folder, 'shared-tail', self.samples))

    def rejects_both(self):
        self.write()
        with self.assertRaises(ValueError):
            DRIVER.validate_accounting(self.folder, 'shared-tail', self.samples)
        with self.assertRaises(ValueError):
            ANALYZER.read_accounting(self.folder, 'shared-tail', self.samples)

    def add_resolutions(self, index, amount):
        self.samples[index]['counters']['lazyValueCalls'] += amount
        self.records[index + 1]['lazyValueCallsAtClose'] += amount
        for record in self.records[index + 2:]:
            record['lazyValueCallsAtOpen'] += amount
            record['lazyValueCallsAtClose'] += amount

    def test_terminal_factor_loss_preserves_raw_difference_and_qualifies(self):
        baseline_samples = copy.deepcopy(self.samples)
        baseline_accounting, _ = self.validate_both()
        self.add_resolutions(1, 1)
        self.records[2]['factorWeakTerminal'] = 1
        candidate_accounting, independent = self.validate_both()
        self.assertEqual(independent['records'][1]['terminalWeakUnion'], 1)
        all_run = {'fixture': 'shared-tail', 'round': 0, 'samples': baseline_samples,
                   'accounting': baseline_accounting}
        omit_run = {'fixture': 'shared-tail', 'round': 0, 'samples': self.samples,
                    'accounting': candidate_accounting}
        audit = DRIVER.dense_pair_audit(all_run, omit_run)
        self.assertTrue(audit['passed'])
        self.assertFalse(audit['queries'][1]['resolverCallsEqual'])
        self.assertEqual(audit['queries'][1]['rawResolverDifferenceOmitMinusAll'], 1)

    def test_weak_union_handles_recovery_joint_and_other_paths(self):
        self.records[1].update({'ordinaryWeak': 1, 'ordinaryWeakRecovered': 1})
        self.records[2].update({'ordinaryWeak': 1, 'jointWeakTerminal': 1, 'factorWeakTerminal': 1})
        self.records[3].update({'ordinaryWeak': 1, 'ordinaryWeakTerminalOther': 1})
        direct, independent = self.validate_both()
        self.assertEqual([record['terminalWeakUnion'] for record in direct['owners'][:3]], [0, 1, 1])
        self.assertEqual([record['terminalWeakUnion'] for record in independent['records'][:3]], [0, 1, 1])

    def test_raw_resolution_is_not_normalized_or_gated_by_weak_count(self):
        self.add_resolutions(4, 19)
        direct, independent = self.validate_both()
        self.assertEqual(direct['owners'][4]['rawResolverCalls'], 119)
        self.assertEqual(independent['records'][4]['terminalWeakUnion'], 0)

    def test_missing_ordinary_outcome_is_rejected(self):
        self.records[1]['ordinaryWeak'] = 1
        self.rejects_both()

    def test_joint_count_without_terminal_factor_is_rejected(self):
        self.records[1].update({'ordinaryWeak': 1, 'jointWeakTerminal': 1})
        self.rejects_both()

    def test_union_cannot_exceed_raw_resolution(self):
        self.records[1]['factorWeakTerminal'] = 101
        self.rejects_both()

    def test_duplicate_compile_ordinal_rejects_equal_owner_totals(self):
        self.records[3]['compileOrdinalAtOpen'] = 2
        self.records[3]['compileOrdinalAtClose'] = 2
        self.rejects_both()

    def test_inter_owner_resolution_gap_is_rejected(self):
        for record in self.records[3:]:
            record['lazyValueCallsAtOpen'] += 1
            record['lazyValueCallsAtClose'] += 1
        self.rejects_both()

    def test_overflow_is_not_silently_dropped(self):
        self.records[0]['overflowCount'] = 1
        self.rejects_both()

    def test_witness_repair_and_refusal_are_never_relabeled_weak(self):
        for key in DRIVER.ZERO_ACCOUNTING_FIELDS:
            with self.subTest(field=key):
                self.records[1][key] = 1
                self.rejects_both()
                self.records[1][key] = 0


if __name__ == '__main__':
    unittest.main(verbosity=2)
